Ext._define('engine.mq.TaskRestful', {
    extend: 'core.Restful',

    resource: 'MQTask',

    getFields: function(cfg) {
        if(!this._fields)
            this._fields = engine.mq.TaskRestful.superclass.getFields.call(this, cfg).concat([
                {type: "string",name: "state"},
                {type: "string",name: "params"},
                {type: "string",name: "uuid"},
                {type: "int",name: "owner", useNull: true},
                {type: "string",name: "owner_unicode"},
                {type: "string",name: "message"},
                {type: "string",name: "description"},
                {type: "string",name: "data"},
                {type: "string",name: "progress_message"},
                {type: "float", name: "progress", useNull: true},
                {type: "date", name: "started_task", dateFormat: "d/m/Y H:i"},
                {type: "date", name: "finished_task", dateFormat: "d/m/Y H:i", useNull: true},
                {type: "boolean", name: "visualized"},
            ]);

        return this._fields;
    }
});


Ext._define('engine.mq.TaskRestfulCustom', {
    extend: 'engine.mq.TaskRestful',

    resource: 'MQTaskCustom',

    markFinished: function(pkset, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute(
                'mark_finished',
                false,
                'POST',
                {
                    params: {
                        pkset: pkset
                    },
                    scope: this,
                    callback: function() {
                        core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success)
                            core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst);
                        else
                            core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), rst.message);
                    },
                    failure: function() {
                        core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), 'Recurso indisponivel no momento.');
                    }
                }
            )
        );
    },
});

