Ext._define("engine.mq.TaskGridCustom", {
    extend: "core.RestfulGrid",

    rest: "engine.mq.TaskRestfulCustom",
    restWindow: "engine.mq.TaskWindow",

    constructor: function (cfg) {
        cfg = cfg || {};
        Ext.apply(cfg, {
            runAutoLoadGrid: false,
            callAutoLoad: false,
        });
        engine.mq.TaskGridCustom.superclass.constructor.call(this, cfg);
        this.getStore().on({
            scope: this,
            load: function () {
                this._autoLoadGrid();
            }
        });
    },

    __rendererItem: function (value, cell, data) {
        var tpl = new Ext.XTemplate(
            '<div style="padding:4px">',
            '<div class="notify-entry" style="font-size:10pt; padding: 5px 0; white-space: normal; line-height: 1.5em">{message}</div>',
            "</div>"
        );

        return tpl.apply(data.data, true);
    },

    _markFinished: function (pkset) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), { msg: "marcando..." });

        mask.show();
        rest.markFinished(
            pkset,
            {
                scope: this,
                fn: function () {
                    this.getStore().reload();
                },
            },
            {
                scope: this,
                fn: function (message) {
                    Ext.Msg.show({
                        title: "Marcando como concluído",
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                    });
                },
            },
            {
                scope: this,
                fn: function () {
                    mask.hide();
                },
            }
        );
    },

    markFinished: function () {
        var selection = this.getSelectionModel().getSelections();

        if (selection.length > 0) {
            Ext.Msg.show({
                title: "Marcando como concluído",
                msg: "Tem certeza que deseja marcar os itens selecionados como concluido?",
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function (btn) {
                    if (btn == "no") return;

                    this._markFinished(
                        selection.map(function (data) {
                            return data.get("pk");
                        })
                    );
                },
            });
        } else
            Ext.Msg.show({
                title: "Marcar como concluído",
                msg: "Primeiro selecione os itens que deseja marcar como concluído.",
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
            });
    },

    markFinishedAll: function () {
        var store = this.getStore();
        var selection = [];
        store.data.items.forEach(function (item) {
            if ((item.data["state"] != "initializing") && (item.data["state"] != "progress"))
                selection.push(item.data["pk"]);
        });

        if (selection.length > 0) {
            Ext.Msg.show({
                title: "Marcando como concluído",
                msg: "Tem certeza que deseja limpar todos itens concluidos?",
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function (btn) {
                    if (btn == "no") return;

                    this._markFinished(selection);
                },
            });
        }
    },

    getRepeatAction: function (cfg) {
        if (!this._repeatAction)
            this._repeatAction = Ext._create("Ext.Button", {
                text: "Repetir",
            });

        return this._repeatAction;
    },

    getFinishedAction: function (cfg) {
        if (!this._finishedAction)
            this._finishedAction = Ext._create("Ext.Button", {
                text: "Concluído",
                iconCls: "icon-core icon-core-success",
                scope: this,
                handler: function () {
                    this.markFinished();
                },
            });

        return this._finishedAction;
    },

    getFinishedAllAction: function (cfg) {
        if (!this._fnishedAllAction)
            this._fnishedAllAction = Ext._create("Ext.Button", {
                text: "Limpar",
                iconCls: "icon-core icon-core-clear",
                scope: this,
                handler: function () {
                    this.markFinishedAll();
                },
            });

        return this._fnishedAllAction;
    },

    getAutoLoadGridAction: function (cfg) {
        if (!this._autoLoadGridAction)
            this._autoLoadGridAction = Ext._create("Ext.form.Checkbox", {
                text: "Atualizar",
                allowBlank: true,
                boxLabel: "Atualizar",
                checked: false,
                scope: this,
                listeners: {
                    scope: this,
                    check: function (btn, checked) {
                        this.runAutoLoadGrid = checked;
                         if (this.runAutoLoadGrid === false) this.callAutoLoad = true;
                        this._autoLoadGrid();
                    },
                },
            });

        return this._autoLoadGridAction;
    },

    reloadGridAuto: function (store) {
        if (!this._reloadGridAuto) {
            this._reloadGridAuto = {
                scope: this,
                run: function () {
                    store.load();
                },
                interval: 10 * 1000,
                duration: 1200 * 1000,
            };
        }

        return this._reloadGridAuto;
    },

    _autoLoadGrid: function () {
        var store = this.getStore();

        if (this.runAutoLoadGrid === false) {
            Ext.TaskMgr.stop(this.reloadGridAuto(store));
            return;
        }

        var pending = false;
        store.data.items.forEach(function (item) {
            if ((item.data["state"] == "initializing") | (item.data["state"] == "progress")) pending = true;
        });

        if (this.callAutoLoad === true && pending) {
            Ext.TaskMgr.start(this.reloadGridAuto(store));
            this.callAutoLoad = false;
        } else if (this.callAutoLoad === false && pending === false) {
            this.callAutoLoad = true;
            Ext.TaskMgr.stop(this.reloadGridAuto(store));
        }
    },

    getColumnModel: function () {
        if (!this._columnModel)
            this._columnModel = Ext._create("Ext.grid.ColumnModel", [
                {
                    header: "Descricao",
                    dataIndex: "__ghost__",
                    id: "autoExpandColumn",
                    renderer: this.__rendererItem,
                },
            ]);

        return this._columnModel;
    },
});

