Ext._define('engine.mq.TaskManage', {
    extend: 'toolkit.widget.TabPanel',

	task: function(value, dispatch){
		dispatch = core.nullValue(dispatch, true);

		if(value !== undefined){
			this._task = value;

			if(dispatch) this.observerTask();
		}
		else
			return this._task;
	},

	observerTask: function() {
		if(this.task()){
			this.getTaskMessagesGrid().enable();
			this.getTaskMessagesGrid().setParam('tasker', this.task());
			this.getTaskMessagesGrid().setFilterProperty('tasker_id', this.task(), 100);
		}
		else{
			this.getTaskMessagesGrid().disable();
			this.getTaskMessagesGrid().getStore().removeAll();
			this.getTaskMessagesGrid().setFilterProperty('tasker_id', 0, 100, false);
		}
    },

    getTaskGrid: function() {
        if(!this._grid) {
            this._grid = Ext._create('engine.mq.TaskGrid', {
                region: 'center',
                minHeight: 300,
                gridAutoLoad: true
            });
			this._grid.getSelectionModel().on({
				scope: this,
				rowselect: function(sm, index, data){
					this.task(data.get('pk'));
				},
				rowdeselect: function(){
					this.task(null);
				},
			});
        }

        return this._grid;
    },

	getTaskMessagesGrid: function() {
	    if(!this._messagesGrid)
	        this._messagesGrid = Ext._create('engine.mq.TaskMessagesGrid', {
	        	// id: 'engine.mq.TaskMessagesGrid',
	        	region: 'south',
				minHeight: 300,
				height: 400,
				split: true,
                gridAutoLoad: false,
                hideColumns: ['tasker_unicode']
	        });

	    return this._messagesGrid;
	},

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'MQ Tasks'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getTaskGrid(),
                    this.getTaskMessagesGrid()
                ]
            }
        );

        engine.mq.TaskManage.superclass.constructor.call(this, cfg);
    }
});

