/*
 * src: /app/root/engine/static/mq/Report.js
 */
Ext._define('engine.mq.Report', {
    extend: 'Object',

    singleton: {
        request: function(cfg, outputFormat) {
            outputFormat = outputFormat || 'PDF';

            Ext.applyIf(cfg, {
                report: undefined,
                params: {},
                reportBuilder: 'MQReportBuilder',
                el: Ext.getBody(),
                waitMessage: 'Processando...',
                showSuccessMsg: true,
            });

            Ext.applyIf(cfg.params, {
                outfile: 'relatorio',
                report_name: 'Relatório',
            });

            if (cfg.report === undefined) {
                throw new Error("engine.mq.Report: Parâmetro 'cfg.report' obrigatório.");
            }

            var mask = new Ext.LoadMask(cfg.el, {
                msg: cfg.waitMessage,
            });

            mask.show();
            Ext.Ajax.request({
                url: core.callAction(cfg.reportBuilder, 'start'),
                params: {
                    report: cfg.report,
                    params: Ext.encode(cfg.params),
                    output_format: outputFormat,
                },
                callback: function() {
                    mask.hide();
                },
                success: function(xhr) {
                    var result = Ext.decode(xhr.responseText);

                    if (!result.success) {
                        Ext.Msg.show({
                            title: 'Solicitando relatório',
                            msg: result.message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    } else if (cfg.showSuccessMsg) {
                        Ext.Msg.show({
                            title: 'Solicitando relatório',
                            msg: result.message,
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK
                        });
                    }
                },
                failure: function() {
                    Ext.Msg.show({
                        title: 'Solicitando relatório',
                        msg: 'Recurso indisponível no momento.',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                },
            });
        }
    }

});


Ext._define('engine.mq.ReportWindow', {
    extend: 'Ext.Window',

    mixins: {
        '1': 'engine.mq.OutputFormatReportMixin'
    },

    width: 355,

    title: 'undefined',

    _filename: 'undefined',

    _reportName: 'undefined',

    _report: 'undefined',

    _waitMessage: 'Gerando relatório...',

    filename: function(params) {
        return this._filename;
    },

    reportName: function(params) {
        return this._reportName;
    },

    prepareDate: function(value, inFormat, outFormat) {
        return Ext.util.Format.date(
            Date.parseDate(value, (inFormat || 'd/m/Y')),
            (outFormat || 'Y-m-d')
        );
    },

    prepareValues: function(values) {
        return values;
    },

    generateReport: function(preventClose) {
        preventClose = core.nullValue(preventClose, false);

        if(!this.getFormPanel().getForm().isValid())
            return;

        var values = this.getFormPanel().getForm().getValues();
        var reportName = this.reportName(values);
        var filename = this.filename(values);

        values = this.prepareValues(values);

        engine.mq.Report.request(
            {
                report: this._report,
                params: Ext.apply(
                    values,
                    {
                        outfile: filename,
                        report_name: reportName
                    }
                ),
                el: this.getEl(),
                waitMessage: this._waitMessage,
            },
            this.outputFormat()
        );

        if(preventClose)
            this.getFormPanel().getForm().reset();
        else
            this.close();
    },

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: []
            });

        return this._formPanel;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.apply(
            cfg,
            {
                modal: true,
                border: false,
                items: [
                    this.getFormPanel(cfg)
                ],
                buttons: [
                    this.getRunReportButton(),
                    {
                        text: 'Limpar',
                        scope: this,
                        handler: function() { this.getFormPanel().getForm().reset();}
                    },
                    {
                        text: 'Fechar',
                        scope: this,
                        handler: function() { this.close(); }
                    }
                ]
            }
        );

        engine.mq.ReportWindow.superclass.constructor.call(this, cfg);
    }
});

/*
 * src: /app/root/engine/static/mq/OutputFormatReportMixin.js
 */
Ext._define('engine.mq.OutputFormatReportMixin', {

	_defaultOutputFormat: 'PDF',

    _reportButtonText: 'Gerar relatório',

	_listOutputFormat: [
	    {
	        title: 'Arquivo PDF',
	        type: 'PDF',
	        iconCls: 'icon-ged icon-ged-application-pdf'
	    },
	    {
	        title: 'Arquivo CSV',
	        type: 'CSV',
	        iconCls: 'icon-ged icon-ged-text-plain',
	    },
        {
	        title: 'Arquivo XLS',
	        type: 'XLS',
	        iconCls: 'icon-ged icon-ged-application-vnd-ms-excel'
	    },
        {
	        title: 'Arquivo ODT',
	        type: 'ODT',
	        iconCls: 'icon-ged icon-ged-application-msword'
	    },
	],

    generateReport: function(preventClose) {
        throw 'Method generateReport not implemented';
    },

	getListOutputFormat: function() {
	    return this._listOutputFormat;
	},

	outputFormat: function() {
        return this._defaultOutputFormat;
    },

	getAllFormatType: function() {
        if(!this._allFormatType) {
            var me = this;
                        
            this._allFormatType = this.getListOutputFormat().map(
                function(item) {
                    return {
                        text: item.title,
                        iconCls: item.iconCls, 
                        handler: function() {
                            me.formatSelected(item.type, item.iconCls);
                        }
                    }  
                }
            );
        }
        
        return this._allFormatType;
    },

    formatSelected: function(format, icon) {
        this._defaultOutputFormat = format.toUpperCase();
        this.getRunReportButton().setIconClass(icon);
        this.generateReport(true);
    },  

    getRunReportButton: function(cfg) {  
        if(!this._runReportSplitBtn) {
            var me = this;
            this._runReportSplitBtn = Ext._create('Ext.Toolbar.SplitButton', {
                text: this._reportButtonText,
                scope: this,
                handler: function() { 
                	me.generateReport(true);
                },
                iconCls: 'icon-ged icon-ged-application-pdf',
                menu : {
                    items: this.getAllFormatType()
                }
            });
        }

        return this._runReportSplitBtn;
    },

});
